result.task=Path(task);
// Derive only the already admitted account ancestry from its real memory
// FD. Never accept a renderer/JS path or account string as a policy root.
Fd memory(owner_->DuplicateMemoryDirectory());
if(memory.value<0||Path(memory.value)!=memory_)throw std::runtime_error("Memory account ancestry is unavailable");
const auto prefix=result.task+"/u/";
constexpr std::string_view suffix="/memory";
if(memory_.size()<=prefix.size()+suffix.size()||!memory_.starts_with(prefix)||!memory_.ends_with(suffix))throw std::runtime_error("Memory account ancestry is unavailable");
const auto account_name=memory_.substr(prefix.size(),memory_.size()-prefix.size()-suffix.size());
if(account_name.empty()||(account_name.size()>1&&account_name.front()=='0')||
   !std::all_of(account_name.begin(),account_name.end(),[](char c){return c>='0'&&c<='9';}))throw std::runtime_error("Memory account ancestry is unavailable");
auto users=OpenRelative(task,"u",true);
auto account=OpenRelative(users.value,account_name,true);
auto child=OpenRelative(account.value,"memory",true);
struct stat held_memory{},named_memory{};
if(fstat(memory.value,&held_memory)||fstat(child.value,&named_memory)||
   held_memory.st_dev!=named_memory.st_dev||held_memory.st_ino!=named_memory.st_ino)throw std::runtime_error("Memory account ancestry changed");
result.task_users=Path(users.value);result.memory_account=Path(account.value);
if(result.task_users!=result.task+"/u"||result.memory_account!=prefix+account_name)throw std::runtime_error("Memory account ancestry is unavailable");
result.held.emplace_back(std::move(memory));result.held.emplace_back(std::move(users));
result.held.emplace_back(std::move(account));result.held.emplace_back(std::move(child));
std::array<char,4096> parent{};

const std::string model_prefix=std::string("models/")+kMemoryModelKey;
auto models=OpenRelative(task,"models",true);
auto family=OpenRelative(models.value,kMemoryModelKey,true);
result.models_root=Path(models.value);result.model_family=Path(family.value);
if(result.models_root!=result.task+"/models"||result.model_family!=result.task+"/"+model_prefix)throw std::runtime_error("Memory model ancestry is unavailable");
result.held.emplace_back(std::move(models));result.held.emplace_back(std::move(family));
auto current=OpenRelative(task,model_prefix+"/CURRENT");
